(function(){'use strict';
var DATA={"label": "Classification Model Trainer - public implementations survey", "rows": [["Jupyter", "36"], ["  Jupyter ", "46"], ["pandas", "20"], ["Cross-validation", "61"], ["  Cross-validation ", "57"], ["SHAP", "83"], ["scikit-learn", "87"], ["  scikit-learn ", "39"], ["", ""], ["Jupyter", "42"]]};

var seen={},kept=[],droppedEmpty=0,droppedDup=0;
